typedef int (*df_cmp_fn)(const void*, const void*);

#define DF_CMP_NUM(T, N) \
static int df_cmp_##N(const void* a, const void* b) { \
  T x = *(const T*)a; \
  T y = *(const T*)b; \
  return (x > y) - (x < y); \
}

